parameters.jsCode:
const inputItems = $input.all();

const folderToTool = {
  // 總 AI 使用
  "diagnostic-supervisor-core": "diagnostic_supervisor_core",
  "obd-acquisition-skill": "obd_acquisition_skill",
  "vehicle-rag-skill": "vehicle_rag_skill",
  "expert-routing-skill": "expert_routing_skill",

  // 六位專家共用的資料庫 Skill
  "vehicle-history-db-skill": "vehicle_history_db_skill",

  // 六位領域專家
  "powertrain-expert": "powertrain_expert",
  "electrical-expert": "electrical_expert",
  "brake-expert": "brake_expert",
  "chassis-expert": "chassis_expert",
  "cooling-hvac-expert": "cooling_hvac_expert",
  "safety-expert": "safety_expert"
};

const skills = {};

for (let index = 0; index < inputItems.length; index++) {
  const item = inputItems[index];
  const binaryInfo = item.binary?.data;

  if (!binaryInfo) {
    continue;
  }

  const directory = binaryInfo.directory || "";
  const folderName = directory
    .split("/")
    .filter(Boolean)
    .pop();

  const skillKey = folderToTool[folderName];

  if (!skillKey) {
    continue;
  }

  const fileBuffer =
    await this.helpers.getBinaryDataBuffer(index, "data");

  skills[skillKey] = fileBuffer.toString("utf8");
}

return [
  {
    json: {
      skills_loaded: Object.keys(skills).length > 0,
      skill_count: Object.keys(skills).length,
      skill_names: Object.keys(skills),
      skills: skills
    }
  }
];

